// Package candidate implements atomic batch approval with audit logging and scoped idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"sort"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"strings"
)

const Operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// Validate role and user/tenant presence
		if u.Role != "approver" || u.User == "" || u.Tenant == "" {
			return protocol.Result{}, false, &protocol.Rejection{Status: 403}
		}

		// Canonicalize and validate IDs
		sortedIDs, err := canonicalIDs(ids)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Validate key format
		if !validKey(key) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 400}
		}

		// Check for null bytes in IDs
		for _, id := range sortedIDs {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer func() { _ = tx.Rollback(ctx) }()

		// Bind app context variables
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Advisory lock on idempotency scope to serialize concurrent replays
		lock, _ := json.Marshal([]string{Operation, u.Tenant, u.User, key})
		if _, err = tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, string(lock)); err != nil {
			return protocol.Result{}, false, err
		}

		// Calculate request fingerprint (SHA-256)
		hash := fingerprint(sortedIDs)

		// Check for existing ActionRequest (replay detection)
		var savedHash string
		var saved []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest"
		 WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, u.Tenant, u.User, Operation, key).Scan(&savedHash, &saved)
		if err == nil {
			// Found existing request in scope
			if savedHash != hash {
				// Same key, different target set - conflict
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			// Same key, same targets - replay with same response
			var result protocol.Result
			if err = json.Unmarshal(saved, &result); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return result, true, nil
		}
		if !errors.Is(err, pgx.ErrNoRows) {
			return protocol.Result{}, false, err
		}

		// Query eligible purchases with row lock
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" WHERE id=ANY($1::text[])
		 AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`, sortedIDs, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All requested IDs must be eligible (atomicity: all or nothing)
		if len(eligible) == 0 || len(eligible) != len(sortedIDs) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Update Purchase status to approved
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[])
		 AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, eligible, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(sortedIDs)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Insert approval audit logs
		_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" ("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
		 SELECT $2,id,$3,$4,$5,'submitted','approved' FROM unnest($1::text[]) AS id`, eligible, u.Tenant, u.User, Operation, key)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Prepare response
		sort.Strings(eligible)
		result := protocol.Result{ApprovedIDs: eligible}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Insert ActionRequest (idempotency record)
		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
		 VALUES ($1,$2,$3,$4,$5,$6::jsonb)`, u.Tenant, u.User, Operation, key, hash, string(response))
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return result, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

// canonicalIDs validates and returns sorted unique IDs
func canonicalIDs(ids []string) ([]string, error) {
	if len(ids) < 1 || len(ids) > 100 {
		return nil, &protocol.Rejection{Status: 400}
	}
	result := append([]string(nil), ids...)
	sort.Strings(result)
	for i, id := range result {
		if len(id) == 0 || len(id) > 100 || !isValidUTF8(id) || (i > 0 && result[i-1] == id) {
			return nil, &protocol.Rejection{Status: 400}
		}
	}
	return result, nil
}

// validKey validates idempotency key format
func validKey(key string) bool {
	if len(key) < 1 || len(key) > 128 {
		return false
	}
	for _, c := range key {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("._:-", c)) {
			return false
		}
	}
	return true
}

// isValidUTF8 checks if a string is valid UTF-8
func isValidUTF8(s string) bool {
	_, ok := utf8.DecodeRuneInString(s)
	return ok != utf8.RuneError || len(s) == 0
}

// fingerprint computes SHA-256 hash of sorted IDs in canonical format
func fingerprint(ids []string) string {
	h := sha256.New()
	fmt.Fprint(h, Operation, "\n")
	for _, id := range ids {
		fmt.Fprintf(h, "%d:%s", len(id), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

func init() {
	var utf8 interface{} // Import package
	_ = utf8
}

